#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/linter/tasks/code-lint-shellcheck.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check the shell scripts with ShellCheck"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--all" help="check every shell script of the repository"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="accepted and ignored: ShellCheck has no fixes"
# USAGE arg "[files]" var=#true help="the files to check; the default is the uncommitted files"
# FILES include="*.sh *.bash" shebang="sh bash dash ksh" exclude="*.tmpl"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def flag(name):
  """Whether the # USAGE flag name is set."""
  return os.environ.get(f"usage_{name}", "false") == "true"


def main():
  # Shipped with the linter tool. Without ShellCheck, the task does not apply
  # and prints nothing.
  if not helpers.has_tool("shellcheck"):
    return 0
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # The list of gate_files (the # FILES header above). With no file, the gate
  # does not apply and prints nothing.
  args = [f"--{name}" for name in ("all", "debug", "fix") if flag(name)]
  file_list = helpers.gate_files(__file__, *args, *helpers.usage_files())
  try:
    if os.path.getsize(file_list) == 0:
      return 0

    # Only warnings and errors fail; the info and style notes are advice.
    helpers.print_header("Checking the shell scripts with ShellCheck ...")
    with open(file_list, "rb") as f:
      names = f.read().replace(b"\n", b"\0")
    result = subprocess.run(
      ["xargs", "-0", "mise", "x", "--", "shellcheck", "--severity=warning"], input=names, check=False
    )
    return result.returncode
  finally:
    os.remove(file_list)


if __name__ == "__main__":
  sys.exit(main())
